"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { CheckCircle, AlertCircle, Edit, Trash2, Loader2, RefreshCw } from "lucide-react";
import Layout from "../Layout"; // Adjust path to your Chef-specific Layout

export default function MealsForNextDayC() {
  const navigate = useNavigate();
  const [meals, setMeals] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isLoading, setIsLoading] = useState(true);

  // Fetch meals for the next day on mount
  useEffect(() => {
    fetchMealsForNextDay();
  }, []);

  const fetchMealsForNextDay = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/meals/next-day`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setMeals(response.data || []);
    } catch (err) {
      setError("Erreur lors de la récupération des repas de demain : " + (err.response?.data?.message || err.message));
    } finally {
      setIsLoading(false);
    }
  };


  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold tracking-tight">Repas de Demain</h2>
                <p className="text-white/80 mt-1 text-sm">Liste des repas prévus pour le lendemain</p>
              </div>
              <button
                onClick={fetchMealsForNextDay}
                className="flex items-center gap-2 text-white hover:text-[#C8A45D/20] transition-colors duration-200"
              >
                <RefreshCw className="h-5 w-5" />
                <span>Rafraîchir</span>
              </button>
            </div>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          <div className="p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-sm font-medium">Chargement des repas...</p>
                </div>
              </div>
            ) : meals.length === 0 ? (
              <p className="text-gray-500 text-center">Aucun repas prévu pour demain.</p>
            ) : (
              <ul className="space-y-4">
                {meals.map((meal) => (
                  <li
                    key={meal._id}
                    className="flex justify-between items-center p-4 bg-gray-50 rounded-xl hover:bg-[#F5F6FA]/30 transition-colors duration-150"
                  >
                    <div>
                      <p className="text-sm font-medium text-gray-900">
                        {meal.mealName} ({meal.type === "Breakfast" ? "Petit-déjeuner" : meal.type === "Lunch" ? "Déjeuner" : "Dîner"})
                      </p>
                      <p className="text-sm text-#333333">Prix: {meal.priceOfMeal} DH</p>
                      <p className="text-sm text-gray-500">
                        Date: {new Date(meal.date).toLocaleDateString("fr-FR")}
                      </p>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </Layout>
  );
}
